    auto savedProject=project;auto savedFile=currentFile;auto savedUndo=undoStack,savedRedo=redoStack;auto savedNotes=selectedNotes;int savedTrack=selectedTrack,savedNote=selectedNote,savedPage=synthPage;bool savedDirty=dirty;auto expanded=browserExpanded;
    releaseKeys();cancelNoteTool();closeCommandPalette();perform(stop);project=emptyProject();currentFile={};selectedTrack=7;selectedNote=-1;selectedNotes.clear();lane()={{0,1,60,.8f}};project.tracks[7].volume=.41f;project.tracks[7].tuning.enabled=true;project.tracks[7].tuning.cents[60]=50;publish();undoStack.clear();redoStack.clear();setSize(1440,940);resetLayout();auto before=JSON::toString(projectToJson(project));auto notes=lane();
